 function changeSort(key:SortKey){setSort({key,asc:sort.key===key&&sortActive?"'!sort.asc:true});setSortActive(true);setPage(1)}
 function exportData(){const rows=selected.size?people.filter(p=>selected.has(p.id)):filtered;const csv='"'\\uFEFF'+[['Имя','Email','Должность','Отдел','Статус','Дата добавления'],...rows.map(p=>[p.name,p.email,p.role,p.department,p.status,p.date])].map(row=>row.map(v=>'\"'+v.replaceAll('\"','\"\"')+'\"').join(';')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='сотрудники.csv';a.click();URL.revokeObjectURL(url);notify("'`Экспортировано сотрудников: ${rows.length}`)}
 return <div className="app-shell">
