type SortKey='name'|'role'|'department'|'status'|'date';
export function App() {
 const [people,setPeople]=useState(initialPeople); const [query,setQuery]=useState(''); const [tab,setTab]=useState('Все сотрудники'); const [department,setDepartment]=useState('all'); const [status,setStatus]=useState('all'); const [filterOpen,setFilterOpen]=useState(false); const [sort,setSort]=useState<{key:SortKey;asc:boolean}>({key:'name',asc:true}); const [sortActive,setSortActive]=useState(false); const [page,setPage]=useState(1); const [pageSize,setPageSize]=useState(8); const [selected,setSelected]=useState<Set<number>>(new Set()); const [toast,setToast]=useState(''); const [addOpen,setAddOpen]=useState(false); const [detail,setDetail]=useState<Person|null>(null); const [newName,setNewName]=useState(''); const [newEmail,setNewEmail]=useState(''); const [newDept,setNewDept]=useState('Дизайн');
 const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),3500)};
 const filtered=useMemo(()=>{
 let rows=people.filter(p=>(p.name+' '+p.email+' '+p.role).toLowerCase().includes(query.toLowerCase())&&(department==='all'||p.department===department)&&(status==='all'||p.status===status)&&(tab==='Все сотрудники'||p.status===tab));
 if(sortActive) rows=[...rows].sort((a,b)=>a[sort.key].localeCompare(b[sort.key],'ru')*(sort.asc?1:-1));return rows;
 },[people,query,department,status,tab,sort,sortActive]);
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize)); const currentPage=Math.min(page,pages); const visible=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize); const allChecked=visible.length>0&&visible.every(p=>selected.has(p.id)); const someChecked=visible.some(p=>selected.has(p.id)); const filterCount=Number(department"'!=='"'all')+Number(status"'!=='"'all');
 function toggle(id:number){setSelected(prev=>{const next=new Set(prev);next.has(id)?next.delete(id):next.add(id);return next})}
 function togglePage(){setSelected(prev=>{const next=new Set(prev);visible.forEach(p=>allChecked?next.delete(p.id):next.add(p.id));return next})}
 function changeSort(key:SortKey){setSort({key,asc:sort.key===key&&sortActive?"'!sort.asc:true});setSortActive(true);setPage(1)}
 function exportData(){const rows=selected.size?people.filter(p=>selected.has(p.id)):filtered;const csv='"'\\uFEFF'+[['Имя','Email','Должность','Отдел','Статус','Дата добавления'],...rows.map(p=>[p.name,p.email,p.role,p.department,p.status,p.date])].map(row=>row.map(v=>'\"'+v.replaceAll('\"','\"\"')+'\"').join(';')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='сотрудники.csv';a.click();URL.revokeObjectURL(url);notify("'`Экспортировано сотрудников: ${rows.length}`)}
 return <div className="app-shell">
