 <div className=\"table-toolbar\"><div className=\"search-field\"><TextInput size=\"l\" placeholder=\"Поиск по имени, почте или должности\" value={query} onUpdate={v=>{setQuery(v);setPage(1)}} startContent={<Icon name=\"search\" size={18}/>} hasClear aria-label=\"Поиск сотрудников\"/></div><div className=\"toolbar-actions\"><div className=\"filter-wrap\"><Button size=\"l\" view={filterCount?'outlined-action':'outlined'} onClick={()=>setFilterOpen("'!filterOpen)}><Icon name="filter" size={18}/>Фильтры{filterCount>0&&<span className="filter-number">{filterCount}</span>}</Button>{filterOpen&&<div className="filter-popover"><div className="popover-heading">Фильтры<button aria-label="Закрыть фильтры" onClick={()=>setFilterOpen(false)}><Icon name="close" size={16}/></button></div><label>Отдел</label><Select width="max" value={[department]} onUpdate={v=>{setDepartment(v[0]);setPage(1)}} options={[{value:'"'all',content:'Все отделы'},...['Дизайн','Разработка','Маркетинг','HR','Продажи'].map(v=>({value:v,content:v}))]}/><label>Статус</label><Select width=\"max\" value={[status]} onUpdate={v=>{setStatus(v[0]);setPage(1)}} options={[{value:'all',content:'Все статусы'},...['Активен','В отпуске','Неактивен'].map(v=>({value:v,content:v}))]}/><Button view=\"flat-secondary\" width=\"max\" onClick={()=>{setDepartment('all');setStatus('all');setPage(1)}}>Сбросить фильтры</Button></div>}</div><Button view=\"outlined\" size=\"l\" onClick={exportData}><Icon name=\"download\" size={17}/>Экспорт<span className=\"export-label\">CSV</span></Button></div></div>
 {selected.size>0&&<div className=\"selection-bar\"><span><strong>Выбрано: {selected.size}</strong><button onClick={()=>setSelected(new Set())}>Снять выделение</button></span><button onClick={exportData}><Icon name=\"download\" size={15}/>Экспорт выбранных</button></div>}
 <div className=\"table-scroll\"><table><thead><tr><th className=\"check-cell\"><Checkbox checked={allChecked} indeterminate={"'!allChecked&&someChecked} onUpdate={togglePage} aria-label="Выбрать все строки на странице"/></th>{([['"'name','Сотрудник'],['role','Должность'],['department','Отдел'],['status','Статус'],['date','Дата добавления']] as [SortKey,string][]).map(([key,label])=><th key={key} aria-sort={sortActive&&sort.key===key?(sort.asc?'ascending':'descending'):'none'}><button className={'sort-button '+(sortActive&&sort.key===key?'sorted':'')} onClick={()=>changeSort(key)}>{label}<span className={sortActive&&sort.key===key&& "'!sort.asc?'"'sort-icon ascending':'sort-icon'}><Icon name=\"arrow\" size={14}/></span></button></th>)}<th className=\"row-menu-cell\"/></tr></thead><tbody>{visible.map(p=><tr key={p.id} className={selected.has(p.id)?'selected-row':''}><td className=\"check-cell\"><Checkbox checked={selected.has(p.id)} onUpdate={()=>toggle(p.id)} aria-label={"'`Выбрать: ${p.name}`}/></td><td><button className="person-cell" onClick={()=>setDetail(p)}><span className={`avatar avatar-${p.color}`}>{initials(p.name)}</span><span><strong>{p.name}</strong><small>{p.email}</small></span></button></td><td><span className="role-text">{p.role}</span></td><td><span className={'"'department-tag dept-'+p.department}>{p.department}</span></td><td><span className={'status-tag '+(p.status==='Активен'?'status-active':p.status==='В отпуске'?'status-away':'status-inactive')}><i/>{p.status}</span></td><td className=\"date-cell\">{dateLabel(p.date)}</td><td className=\"row-menu-cell\"><button className=\"row-more\" aria-label={"'`Подробнее: ${p.name}`} onClick={()=>setDetail(p)}>···</button></td></tr>)}</tbody></table>{visible.length===0&&<div className="empty-state"><Icon name="search" size={30}/><h3>Сотрудники не найдены</h3><p>Попробуйте другой запрос или сбросьте фильтры.</p><Button view="outlined" onClick={()=>{setQuery('"'');setDepartment('all');setStatus('all');setTab