 <div className=\"stat-card\"><div><span className=\"stat-label\">Активные сотрудники</span><div className=\"stat-value\">{people.filter(p=>p.status==='Активен').length}<span className=\"stat-note\"><i/>В команде</span></div><span className=\"stat-caption\">создаём отличные продукты вместе</span></div><span className=\"stat-icon green\"><Icon name=\"check\" size={22}/></span></div>
 <div className=\"stat-card\"><div><span className=\"stat-label\">Отделы</span><div className=\"stat-value\">5<span className=\"department-dots\"><i>Д</i><i>Р</i><i>М</i><i>+2</i></span></div><span className=\"stat-caption\">разные экспертизы, одна команда</span></div><span className=\"stat-icon blue\"><Icon name=\"folder\" size={22}/></span></div></div>
